(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,63059,69251,e=>{"use strict";let t=(0,e.i(75254).default)("chevron-right",[["path",{d:"m9 18 6-6-6-6",key:"mthhwq"}]]);e.s(["ChevronRight",()=>t],63059);let o={"english-basics":{title:"Alphabet & Phonics",color:"#fbbf24",sections:[{id:"en-basics-sec",title:"Fundamentals",unlocked:!0,lessons:[{id:"english-basics",title:"Alphabet & Phonics",icon:"🔤",xp:10,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The Letter A",content:'A is for Apple. It makes an "ah" sound.'},{type:"multiple_choice",question:"Which word starts with A?",options:["Banana","Apple","Cat"],correct:1}]}]}]},"robotics-kids":{title:"Visual Logic: Block Robotics",color:"#60a5fa",sections:[{id:"robotics-sec",title:"Intro to Robotics",unlocked:!0,lessons:[{id:"robotics-kids",title:"Visual Logic: Block Robotics",icon:"🤖",xp:15,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Commanding the Bot",content:'Drag the "Move Forward" block.'},{type:"multiple_choice",question:"To turn right?",options:["Turn Left","Turn Right"],correct:1}]}]}]},english:{title:"English Adventure",color:"#fbbf24",sections:[{id:"en-a1",title:"A1 — Beginner",tier:"A1",unlocked:!0,lessons:[{id:"en-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:100,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"I ___ a student.",options:["is","am","are"],correct:1},{type:"multiple_choice",question:"She ___ two cats.",options:["have","has","having"],correct:1,explanation:"With he/she/it the verb takes -s: has, not have."},{type:"multiple_choice",question:"They ___ from Spain.",options:["is","am","are"],correct:2,explanation:"Plural subjects (they, we, you) take are."},{type:"multiple_choice",question:"Which sentence is a question?",options:["You are tired.","Are you tired?","You tired are."],correct:1,explanation:"A yes/no question in English moves the verb to be in front of the subject."}]}]},{id:"en-a2",title:"A2 — elementary",tier:"A2",unlocked:!0,lessons:[{id:"en-a2-test",title:"A2 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"I have ___ finished my homework.",options:["already","yet","still"],correct:0,explanation:"Already is used in affirmative sentences with the present perfect to show something happened sooner than expected."},{type:"multiple_choice",question:"If it rains, I ___ stay home.",options:["will","would","am"],correct:0,explanation:"First conditional: if + present, will + base verb, for a real future possibility."},{type:"multiple_choice",question:"This book is ___ than that one.",options:["interesting","more interesting","most interesting"],correct:1,explanation:"Comparing two things uses the comparative form: more interesting."},{type:"multiple_choice",question:"She said she ___ tired.",options:["is","was","be"],correct:1,explanation:"Reported speech shifts present tense back one step into the past: is becomes was."}]}]},{id:"en-b1",title:"B1 — Intermediate",tier:"B1",unlocked:!0,lessons:[{id:"en-b1-test",title:"B1 Proficiency Test",icon:"🔯",xp:200,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"By the time we arrived, the film ___ already started.",options:["has","had","have"],correct:1,explanation:"Past perfect (had + past participle) marks an action completed before another past action."},{type:"multiple_choice",question:"The report ___ by the team yesterday.",options:["was written","wrote","is writing"],correct:0,explanation:"The passive voice (was + past participle) is used when the focus is on the report, not who wrote it."},{type:"multiple_choice",question:"I wish I ___ more time to prepare.",options:["have","had","will have"],correct:1,explanation:"Wish + past tense expresses regret about a present situation."},{type:"multiple_choice",question:"Choose the correctly punctuated sentence.",options:["Although it was raining, we went out.","Although it was raining we went out","Although, it was raining, we went out."],correct:0,explanation:"A comma follows an introductory subordinate clause; none belongs after although."}]}]}]},spanish:{title:"Spanish Quest",color:"#ef4444",sections:[{id:"sp-a1",title:"A1 — The Beginning",tier:"A1",unlocked:!0,lessons:[{id:"sp-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:100,unlocked:!0,type:"test",work:"control",exercises:[{type:"translate",question:"Hola",correct:"Hello"},{type:"translate",question:"Gracias",correct:"Thank you",acceptable:["Thanks"]},{type:"multiple_choice",question:"Yo ___ estudiante.",options:["soy","eres","es"],correct:0,explanation:"Soy is the first-person singular of ser (to be): yo soy."},{type:"multiple_choice",question:'"La casa" means',options:["the house","a house","her house"],correct:0,explanation:"La is the feminine definite article the; casa is feminine."}]}]},{id:"sp-a2",title:"A2 — Fundamental",tier:"A2",unlocked:!0,lessons:[{id:"sp-a2-test",title:"A2 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"Ayer yo ___ al cine.",options:["voy","fui","iré"],correct:1,explanation:"Fui is the preterite of ir (to go), used for a completed action in the past: ayer fui."},{type:"multiple_choice",question:'"Estoy cansado" means',options:["I am tired","I am a teacher","I am here"],correct:0,explanation:"Estar is used for temporary states like tiredness; cansado means tired."},{type:"translate",question:"el libro",correct:"the book"},{type:"multiple_choice",question:'Which is correct for "we eat"?',options:["comemos","comen","como"],correct:0,explanation:"Comemos is the first-person plural (nosotros) form of comer."}]}]}]},german:{title:"German Pursuit",color:"#fde047",sections:[{id:"de-a1",title:"A1 — Beginner",tier:"A1",unlocked:!0,lessons:[{id:"de-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:100,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"Hallo?",options:["Hello","Bye"],correct:0}]}]}]},catalan:{title:"Català Discovery",color:"#f97316",sections:[{id:"ca-base",title:"Mediterranean Basics",unlocked:!0,lessons:[{id:"ca-l1",title:"First Words",icon:"☀️",xp:12,unlocked:!0,work:"classwork",exercises:[{type:"multiple_choice",question:"Bon dia?",options:["Good morning","Good night"],correct:0}]}]}]},ukrainian:{title:"Ukrainian Heart",color:"#ffd700",sections:[{id:"uk-a1",title:"A1 — Beginnings",tier:"A1",unlocked:!0,lessons:[{id:"uk-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"translate",question:"Дякую",correct:"Thank you",acceptable:["Thanks"]},{type:"multiple_choice",question:'"Привіт" is used to say',options:["Hello","Goodbye","Please"],correct:0,explanation:"Привіт is an informal greeting, equivalent to hello or hi."},{type:"multiple_choice",question:"Я ___ студент.",options:["є","(nothing, dropped)","був"],correct:1,explanation:'The present-tense form of "to be" is normally omitted in Ukrainian: Я студент, not Я є студент.'},{type:"translate",question:"книга",correct:"book"}]}]}]},russian:{title:"Russian Legacy",color:"#3b82f6",sections:[{id:"ru-a1",title:"A1 — Basics",tier:"A1",unlocked:!0,lessons:[{id:"ru-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"translate",question:"Спасибо",correct:"Thank you",acceptable:["Thanks"]},{type:"multiple_choice",question:'"Привет" is used to say',options:["Hello","Goodbye","Sorry"],correct:0,explanation:"Привет is an informal greeting, equivalent to hello or hi."},{type:"multiple_choice",question:"Choose the correct form: Я ___ книгу.",options:["читаю","читаешь","читает"],correct:0,explanation:"Читаю is the first-person singular (I read) form of читать."},{type:"translate",question:"дом",correct:"house"}]}]}]},physics:{title:"Applied Physics",color:"#06b6d4",sections:[{id:"ph-a1",title:"Phase 1: Motion",tier:"A1",unlocked:!0,lessons:[{id:"ph-l1",title:"Newtonian Laws",icon:"🍎",xp:20,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"First Law of Motion",content:"An object at rest stays at rest unless acted upon by a force."},{type:"multiple_choice",question:"Who defined the Laws of Motion?",options:["Einstein","Newton","Curie"],correct:1}]},{id:"ph-a1-test",title:"Physics A1 Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"An object at rest stays at rest unless acted on by a",options:["force","shadow","clock"],correct:0,explanation:"This is Newton’s First Law: no net force, no change in motion."},{type:"multiple_choice",question:"Newton’s Second Law relates force, mass and",options:["temperature","acceleration","color"],correct:1,explanation:"F = m * a: force equals mass times acceleration."},{type:"multiple_choice",question:"Newton’s Third Law says every action has an equal and opposite",options:["reaction","shadow","delay"],correct:0,explanation:"Forces always come in equal, opposite pairs between two bodies."},{type:"multiple_choice",question:"If two objects are each in thermal equilibrium with a third, they are",options:["in equilibrium with each other","always at the same pressure","unrelated"],correct:0,explanation:"This is the 0th law of thermodynamics: equilibrium with a common third body implies equilibrium with each other."}]}]},{id:"ph-a2",title:"Phase 2: Energy",tier:"A2",unlocked:!0,lessons:[{id:"ph-l2",title:"Conservation of Energy",icon:"⚡",xp:40,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Energy Conservation",content:"Energy cannot be created or destroyed, only transformed."},{type:"multiple_choice",question:"Kinetic energy is energy of?",options:["Rest","Motion","Height"],correct:1}]}]}]},programming:{title:"Strategic Programming",color:"#22d3ee",sections:[{id:"prog-a1",title:"Logic & Loops",tier:"A1",unlocked:!0,lessons:[{id:"prog-l1",title:"The If Statement",icon:"❓",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Conditionals",content:'An "if" statement checks a condition before executing code.'},{type:"multiple_choice",question:"Result of if(true) { print(1) }?",options:["0","1","Error"],correct:1}]}]},{id:"prog-a2",title:"Data Structures",tier:"A2",unlocked:!0,lessons:[{id:"prog-l2",title:"Arrays & Lists",icon:"📋",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Storing Data",content:"Arrays store a collection of items at contiguous memory locations."},{type:"multiple_choice",question:"First index of an array?",options:["0","1"],correct:0}]}]},{id:"prog-b1",title:"Algorithms & Complexity",tier:"B1",unlocked:!0,lessons:[{id:"prog-l3",title:"Binary Search",icon:"🔍",xp:60,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Efficient Search",content:"Binary search finds an item in a sorted list by repeatedly halving the search space."},{type:"multiple_choice",question:"What is the time complexity of linear search on a list of n items?",options:["O(1)","O(n)","O(log n)"],correct:1,explanation:"Linear search may check every item once, in the worst case n comparisons: O(n)."},{type:"multiple_choice",question:"What is the time complexity of binary search on a sorted list of n items?",options:["O(n)","O(log n)","O(n^2)"],correct:1,explanation:"Each step of binary search halves the remaining range, giving O(log n)."},{type:"multiple_choice",question:"Binary search requires the list to be",options:["sorted","short","unique values only"],correct:0,explanation:"Halving only discards the correct half when the list is sorted; on an unsorted list the trick fails."}]}]}]},"programming-basics":{title:"Programming Foundations",color:"#22d3ee",sections:[{id:"pf-a1",title:"What a program is",tier:"A1",unlocked:!0,lessons:[{id:"pf-l1",title:"Instructions and order",icon:"📜",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"A program is a list of steps",content:"A computer does exactly what it is told, in the order it is told. Nothing is guessed, nothing is skipped. Writing a program means writing that list precisely enough for a machine to follow it without asking you anything."},{type:"multiple_choice",question:"Making tea: (1) pour the water (2) boil the water (3) add the teabag. What is wrong?",options:["Nothing is wrong","The order is wrong","A step is missing"],correct:1,explanation:"All three steps are present, but pouring before boiling gives cold tea. Order carries meaning."},{type:"multiple_choice",question:"Why must instructions be exact?",options:["Computers are slow","A computer cannot guess what you meant","Programs are long"],correct:1,explanation:"A person fills gaps from experience. A machine has none: an unclear step becomes an error or a wrong result."},{type:"word_arrange",question:"Order the steps: opening a door with a key",words:["take out the key","put it in the lock","turn the key","pull the handle"],correct:[0,1,2,3]}]},{id:"pf-l1b",title:"Values and names",icon:"📦",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"A name holds a value",content:"A program keeps values: a number, a piece of text, a yes-or-no answer. Each gets a name so later steps can use it. Naming is not decoration — it is how one step hands its result to the next."},{type:"multiple_choice",question:"price = 10, then price = 25. What is in price now?",options:["10","25","both"],correct:1,explanation:"Assignment replaces. A name holds one value at a time; the old one is gone."},{type:"code_output",question:"What is printed?\n\na = 3\nb = 4\na = b\nprint(a + b)",options:["7","8","6"],correct:1,explanation:"After a = b both names hold 4, so the sum is 8. Assignment copies the value; it does not tie the names together."},{type:"multiple_choice",question:"Best name for the count of unread letters?",options:["x","unread_count","n1"],correct:1,explanation:"A name is read far more often than written. Your own code from last month is someone else’s code."}]},{id:"pf-l1c",title:"Kinds of values",icon:"🔣",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Numbers and text are different things",content:'The number 12 and the text "12" look the same on screen and behave differently. Numbers add up; text joins end to end. Many beginner bugs are one kind quietly used where the other was meant.'},{type:"code_output",question:'What is printed?\n\nprint("2" + "3")',options:["5","23","an error"],correct:1,explanation:"Two pieces of text are joined: 23. For 5 you need numbers: 2 + 3."},{type:"multiple_choice",question:"A phone number is best stored as",options:["a number","text"],correct:1,explanation:"Phone numbers are never added, and a leading zero would be lost in a number. That makes them text."}]}]},{id:"pf-a2",title:"Choice, repetition, structure",tier:"A2",unlocked:!0,lessons:[{id:"pf-l2",title:"Conditions",icon:"🔀",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"A fork in the road",content:"A condition asks a yes-or-no question and runs one branch or the other. This is where a program stops being a fixed list and starts responding to what it is given."},{type:"code_output",question:'age = 15. What is printed?\n\nif age >= 18:\n    print("adult")\nelse:\n    print("minor")',options:["adult","minor","both"],correct:1,explanation:"15 >= 18 is false, so only the else branch runs. Exactly one branch runs, never both."},{type:"multiple_choice",question:'When is "it is raining AND I have an umbrella" true?',options:["When at least one holds","Only when both hold","Always"],correct:1,explanation:"AND needs both; at least one is OR. Confusing them is a common source of wrong conditions."},{type:"multiple_choice",question:"Which lets in ages 14 to 18 inclusive?",options:["age > 14 and age < 18","age >= 14 and age <= 18","age >= 14 or age <= 18"],correct:1,explanation:"Inclusive bounds need >= and <=. The third is true for every age, since any number satisfies one half."}]},{id:"pf-l2b",title:"Loops",icon:"🔄",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Say it once, do it many times",content:"A loop repeats steps while something stays true, or once per item in a list. The programmer’s job is to be sure it ends: a loop whose condition never turns false runs forever."},{type:"code_output",question:"What is printed?\n\ntotal = 0\nfor n in [1, 2, 3, 4]:\n    total = total + n\nprint(total)",options:["4","10","24"],correct:1,explanation:"The total grows 1, 3, 6, 10. This accumulator pattern appears in almost every program."},{type:"code_output",question:'How many times is the line printed?\n\ni = 0\nwhile i < 3:\n    print("hi")\n    i = i + 1',options:["2","3","forever"],correct:1,explanation:"i takes 0, 1, 2 and then the condition fails. Remove i = i + 1 and it would indeed run forever."},{type:"multiple_choice",question:"What makes a loop never stop?",options:["Too many items","Nothing inside moves the condition towards false","A condition false at the start"],correct:1,explanation:"If the body never changes what the condition tests, nothing else will."}]},{id:"pf-l2c",title:"Lists",icon:"📋",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Many values under one name",content:"A list holds values in order under a single name, and each has a position. Counting starts at zero: the first item is at position 0. That is a convention, and forgetting it is the most common off-by-one mistake."},{type:"multiple_choice",question:"First position in a list?",options:["0","1"],correct:0,explanation:"Position is an offset from the start, and the first item is zero steps in."},{type:"code_output",question:'What is printed?\n\nnames = ["ann", "bob", "cid"]\nprint(names[1])',options:["ann","bob","cid"],correct:1,explanation:"Position 1 is the second item, because positions start at 0."},{type:"code_output",question:'A list of 3 items. What happens?\n\nnames = ["ann", "bob", "cid"]\nprint(names[3])',options:["cid","an error","nothing"],correct:1,explanation:"Valid positions are 0, 1, 2. Position 3 is past the end — the classic off-by-one."}]},{id:"pf-l2d",title:"Functions",icon:"🧩",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Name a piece of work once",content:"A function is a named piece of work: you hand it values, it hands back a result. It exists so an idea is written once, tested once and fixed in one place. A program without functions repeats itself, and repetition is where errors hide."},{type:"code_output",question:"What is printed?\n\ndef double(x):\n    return x * 2\n\nprint(double(5) + double(2))",options:["14","10","7"],correct:0,explanation:"double(5) is 10 and double(2) is 4, so 14. The function runs once per call."},{type:"multiple_choice",question:"Why move repeated steps into a function?",options:["The program runs faster","One fix applies everywhere it is used","It uses less memory"],correct:1,explanation:"The gain is maintenance, not speed. The same steps copied five times means five fixes — and four forgotten ones."},{type:"word_arrange",question:"Order the parts of a function call",words:["give it values","it does the work","it returns a result","the result is used"],correct:[0,1,2,3]}]}]},{id:"pf-b1",title:"Thinking like a programmer",tier:"B1",unlocked:!0,lessons:[{id:"pf-l3",title:"Errors and finding them",icon:"🐛",xp:60,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Wrong is the normal state of new code",content:"Errors come in two kinds. The program refuses to run — a typo, a missing bracket — and the machine tells you where. Or it runs and gives a wrong answer, and nobody tells you anything. The second kind is the real work: you check what you believe against what is actually there."},{type:"code_output",question:"The average of 2 and 4 should be 3. What is printed?\n\nprint(2 + 4 / 2)",options:["3","4","3.0"],correct:1,explanation:"Division runs before addition: 2 + 2 = 4. It needs brackets: (2 + 4) / 2. The program was never broken, only wrong."},{type:"multiple_choice",question:"It runs but the answer is wrong. First step?",options:["Rewrite from scratch","Look at the actual values at each step","Try random changes"],correct:1,explanation:"A wrong answer means some step differs from your assumption. Looking at real values finds the gap; guessing hides it."},{type:"multiple_choice",question:"It works on 5 items and fails on an empty list. That means",options:["The computer is faulty","You never considered the empty case","Empty lists are not allowed"],correct:1,explanation:"Edge cases — empty, one item, the largest — are where assumptions show. Think of them before the user does."}]},{id:"pf-l3b",title:"From idea to steps",icon:"🧭",xp:60,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"An algorithm is a plan that always ends",content:"Before writing code you settle three things: what you are given, what you want, and the steps between. A plan that may never finish is not an algorithm. Languages differ; this part does not."},{type:"word_arrange",question:"Order the steps: find the largest number in a list",words:["take the first number as the largest so far","look at the next number","if it is bigger, it becomes the largest so far","when the list ends, report the largest"],correct:[0,1,2,3]},{type:"multiple_choice",question:"Looking up a word by opening the middle and halving each time is fast because",options:["Dictionaries are small","Each step discards half of what is left","Only dictionaries are sorted"],correct:1,explanation:"This is binary search: a thousand pages take about ten steps, because each step halves the remainder."},{type:"multiple_choice",question:"What is true of every algorithm?",options:["It is written in a specific language","It ends after a finite number of steps","It is short"],correct:1,explanation:"Termination is part of the definition. A plan that runs forever solves nothing, however elegant."}]}]}]},chess:{title:"Chess Mastery",color:"#a855f7",sections:[{id:"chess-a1",title:"Board Control",tier:"A1",unlocked:!0,lessons:[{id:"chess-l1",title:"The Center Square",icon:"🏰",xp:30,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Opening Strategy",content:"Control the four central squares to dominate the board."},{type:"multiple_choice",question:"Most important squares?",options:["Edges","Corners","Center"],correct:2}]}]},{id:"chess-a2",title:"Tactics Arena",tier:"A2",unlocked:!0,lessons:[{id:"chess-l2",title:"The Fork",icon:"🍴",xp:50,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Tactical Patterns",content:"A fork occurs when one piece attacks two or more enemy pieces simultaneously."},{type:"multiple_choice",question:"Best piece for a fork?",options:["Pawn","Knight","King"],correct:1}]}]}]},french:{title:"French Journey",color:"#3b82f6",sections:[{id:"french-a1-1",title:"First words",tier:"A1",unlocked:!0,lessons:[{id:"french-a1-greetings",title:"Greetings",icon:"👋",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Greetings",content:"Bonjour is for the day and bonsoir for the evening; salut is only for people you know. French adds s'il vous plaît and merci far more readily than English adds please and thanks -- leaving them out sounds abrupt."},{type:"multiple_choice",question:"What does «bonjour» mean?",options:["hello / good morning","thank you","good evening"],correct:0,explanation:"«bonjour» means “hello / good morning”."},{type:"multiple_choice",question:"What does «salut» mean?",options:["please","hi","yes"],correct:1,explanation:"«salut» means “hi”."},{type:"multiple_choice",question:"What does «non» mean?",options:["hello / good morning","thank you","no"],correct:2,explanation:"«non» means “no”."},{type:"translate",question:"Write in French: “thank you”",correct:"merci",explanation:"“thank you” is «merci»."},{type:"translate",question:"Write in French: “goodbye”",correct:"au revoir",explanation:"“goodbye” is «au revoir»."}]},{id:"french-a1-introductions",title:"Who I am",icon:"🧑",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Who I am",content:"The verb to be changes with the person: je suis, tu es, il est, elle est, nous sommes. Tu is for friends and children; with a stranger you say vous. Je m'appelle literally means I call myself."},{type:"multiple_choice",question:"What does «je suis» mean?",options:["I am","you are","he is"],correct:0,explanation:"«je suis» means “I am”."},{type:"multiple_choice",question:"What does «elle est» mean?",options:["we are","she is","my name is"],correct:1,explanation:"«elle est» means “she is”."},{type:"multiple_choice",question:"What does «enchanté» mean?",options:["I am","you are","nice to meet you"],correct:2,explanation:"«enchanté» means “nice to meet you”."},{type:"translate",question:"Write in French: “I am”",correct:"je suis",explanation:"“I am” is «je suis»."},{type:"translate",question:"Write in French: “we are”",correct:"nous sommes",explanation:"“we are” is «nous sommes»."}]},{id:"french-a1-numbers",title:"Numbers 1-10",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers 1-10",content:"Un, deux, trois. The final consonant is usually silent: deux sounds like deu, trois like trwa. Un also means a, so un chat is both one cat and a cat."},{type:"multiple_choice",question:"What does «un» mean?",options:["one","two","three"],correct:0,explanation:"«un» means “one”."},{type:"multiple_choice",question:"What does «six» mean?",options:["seven","six","eight"],correct:1,explanation:"«six» means “six”."},{type:"multiple_choice",question:"What does «dix» mean?",options:["one","two","ten"],correct:2,explanation:"«dix» means “ten”."},{type:"translate",question:"Write in French: “two”",correct:"deux",explanation:"“two” is «deux»."},{type:"translate",question:"Write in French: “five”",correct:"cinq",explanation:"“five” is «cinq»."}]}]},{id:"french-a1-2",title:"People and things",tier:"A1",unlocked:!0,lessons:[{id:"french-a1-family",title:"Family",icon:"👪",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Family",content:"Every French noun is masculine or feminine, and the word for the shows it: le père, la mère. Learn the noun together with its le or la -- the gender cannot be guessed from the meaning."},{type:"multiple_choice",question:"What does «la mère» mean?",options:["the mother","the father","the brother"],correct:0,explanation:"«la mère» means “the mother”."},{type:"multiple_choice",question:"What does «la sœur» mean?",options:["the son","the sister","the daughter"],correct:1,explanation:"«la sœur» means “the sister”."},{type:"multiple_choice",question:"What does «les parents» mean?",options:["the mother","the father","the parents"],correct:2,explanation:"«les parents» means “the parents”."},{type:"translate",question:"Write in French: “the father”",correct:"le père",explanation:"“the father” is «le père»."},{type:"translate",question:"Write in French: “the brother”",correct:"le frère",explanation:"“the brother” is «le frère»."}]},{id:"french-a1-food",title:"Food and drink",icon:"🍞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Food and drink",content:"Before a vowel le and la shorten to l': l'eau, not la eau. With food you usually say du, de la or de l' -- some -- rather than naming the thing bare: je veux du pain, I want some bread."},{type:"multiple_choice",question:"What does «le pain» mean?",options:["the bread","the water","the milk"],correct:0,explanation:"«le pain» means “the bread”."},{type:"multiple_choice",question:"What does «le fromage» mean?",options:["the apple","the cheese","the coffee"],correct:1,explanation:"«le fromage» means “the cheese”."},{type:"multiple_choice",question:"What does «le thé» mean?",options:["the bread","the water","the tea"],correct:2,explanation:"«le thé» means “the tea”."},{type:"translate",question:"Write in French: “the bread”",correct:"le pain",explanation:"“the bread” is «le pain»."},{type:"translate",question:"Write in French: “the milk”",correct:"le lait",explanation:"“the milk” is «le lait»."}]},{id:"french-a1-have",title:"I have",icon:"📚",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"I have",content:"To have: j'ai, tu as, il a, nous avons. Je shortens to j' before a vowel. French uses avoir where English uses to be for age and hunger: j'ai faim is literally I have hunger."},{type:"multiple_choice",question:"What does «j'ai» mean?",options:["I have","you have","he has"],correct:0,explanation:"«j'ai» means “I have”."},{type:"multiple_choice",question:"What does «un livre» mean?",options:["a house","a book","a cat"],correct:1,explanation:"«un livre» means “a book”."},{type:"multiple_choice",question:"What does «un chien» mean?",options:["I have","you have","a dog"],correct:2,explanation:"«un chien» means “a dog”."},{type:"translate",question:"Write in French: “I have”",correct:"j'ai",explanation:"“I have” is «j'ai»."},{type:"translate",question:"Write in French: “a cat”",correct:"un chat",explanation:"“a cat” is «un chat»."}]}]},{id:"french-a1-3",title:"Getting around",tier:"A1",unlocked:!0,lessons:[{id:"french-a1-questions",title:"Questions and directions",icon:"❓",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Questions and directions",content:"Question words start the sentence: où est la gare ? -- where is the station? In speech a plain statement with a rising voice is already a question: tu viens? À gauche and à droite are all you need to follow directions."},{type:"multiple_choice",question:"What does «où» mean?",options:["where","when","how"],correct:0,explanation:"«où» means “where”."},{type:"multiple_choice",question:"What does «combien» mean?",options:["who","how much","to the left"],correct:1,explanation:"«combien» means “how much”."},{type:"multiple_choice",question:"What does «à droite» mean?",options:["where","when","to the right"],correct:2,explanation:"«à droite» means “to the right”."},{type:"translate",question:"Write in French: “where”",correct:"où",explanation:"“where” is «où»."},{type:"translate",question:"Write in French: “to the right”",correct:"à droite",explanation:"“to the right” is «à droite»."}]},{id:"french-a1-days",title:"Days and time",icon:"📅",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Days and time",content:"Days are not capitalised in French, and the week starts on lundi. Le lundi means on Mondays, every week; lundi alone means this Monday."},{type:"multiple_choice",question:"What does «lundi» mean?",options:["Monday","Tuesday","Wednesday"],correct:0,explanation:"«lundi» means “Monday”."},{type:"multiple_choice",question:"What does «samedi» mean?",options:["Sunday","Saturday","today"],correct:1,explanation:"«samedi» means “Saturday”."},{type:"multiple_choice",question:"What does «hier» mean?",options:["Monday","Tuesday","yesterday"],correct:2,explanation:"«hier» means “yesterday”."},{type:"translate",question:"Write in French: “tomorrow”",correct:"demain",explanation:"“tomorrow” is «demain»."},{type:"translate",question:"Write in French: “Monday”",correct:"lundi",explanation:"“Monday” is «lundi»."}]}]}]},italian:{title:"Italian Voyage",color:"#22c55e",sections:[{id:"italian-a1-1",title:"First words",tier:"A1",unlocked:!0,lessons:[{id:"italian-a1-greetings",title:"Greetings",icon:"👋",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Greetings",content:"Ciao is both hello and goodbye, but only between people who know each other. With anyone else it is buongiorno by day and buonasera from late afternoon. Every letter is pronounced; there are almost no silent ones."},{type:"multiple_choice",question:"What does «ciao» mean?",options:["hi / bye","thank you","good morning"],correct:0,explanation:"«ciao» means “hi / bye”."},{type:"multiple_choice",question:"What does «buonasera» mean?",options:["please","good evening","yes"],correct:1,explanation:"«buonasera» means “good evening”."},{type:"multiple_choice",question:"What does «no» mean?",options:["hi / bye","thank you","no"],correct:2,explanation:"«no» means “no”."},{type:"translate",question:"Write in Italian: “thank you”",correct:"grazie",explanation:"“thank you” is «grazie»."},{type:"translate",question:"Write in Italian: “goodbye”",correct:"arrivederci",explanation:"“goodbye” is «arrivederci»."}]},{id:"italian-a1-introductions",title:"Who I am",icon:"🧑",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Who I am",content:"To be: io sono, tu sei, lui è, lei è, noi siamo. The pronoun is usually dropped because the verb already shows the person: sono Marco, I am Marco. Lei with a capital is also the polite you."},{type:"multiple_choice",question:"What does «io sono» mean?",options:["I am","you are","he is"],correct:0,explanation:"«io sono» means “I am”."},{type:"multiple_choice",question:"What does «lei è» mean?",options:["we are","she is","my name is"],correct:1,explanation:"«lei è» means “she is”."},{type:"multiple_choice",question:"What does «piacere» mean?",options:["I am","you are","nice to meet you"],correct:2,explanation:"«piacere» means “nice to meet you”."},{type:"translate",question:"Write in Italian: “I am”",correct:"io sono",explanation:"“I am” is «io sono»."},{type:"translate",question:"Write in Italian: “we are”",correct:"noi siamo",explanation:"“we are” is «noi siamo»."}]},{id:"italian-a1-numbers",title:"Numbers 1-10",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers 1-10",content:"Uno, due, tre. Uno changes before a noun like the word a: un libro, una casa. Double consonants are really held longer -- sette and otto are not sete and oto."},{type:"multiple_choice",question:"What does «uno» mean?",options:["one","two","three"],correct:0,explanation:"«uno» means “one”."},{type:"multiple_choice",question:"What does «sei» mean?",options:["seven","six","eight"],correct:1,explanation:"«sei» means “six”."},{type:"multiple_choice",question:"What does «dieci» mean?",options:["one","two","ten"],correct:2,explanation:"«dieci» means “ten”."},{type:"translate",question:"Write in Italian: “two”",correct:"due",explanation:"“two” is «due»."},{type:"translate",question:"Write in Italian: “five”",correct:"cinque",explanation:"“five” is «cinque»."}]}]},{id:"italian-a1-2",title:"People and things",tier:"A1",unlocked:!0,lessons:[{id:"italian-a1-family",title:"Family",icon:"👪",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Family",content:"Nouns ending in -o are usually masculine, in -a feminine: il fratello, la sorella. Padre and madre end in -e and have to be learned with their article. With one family member the article drops after my: mia madre, not la mia madre."},{type:"multiple_choice",question:"What does «la madre» mean?",options:["the mother","the father","the brother"],correct:0,explanation:"«la madre» means “the mother”."},{type:"multiple_choice",question:"What does «la sorella» mean?",options:["the son","the sister","the daughter"],correct:1,explanation:"«la sorella» means “the sister”."},{type:"multiple_choice",question:"What does «i genitori» mean?",options:["the mother","the father","the parents"],correct:2,explanation:"«i genitori» means “the parents”."},{type:"translate",question:"Write in Italian: “the father”",correct:"il padre",explanation:"“the father” is «il padre»."},{type:"translate",question:"Write in Italian: “the brother”",correct:"il fratello",explanation:"“the brother” is «il fratello»."}]},{id:"italian-a1-food",title:"Food and drink",icon:"🍞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Food and drink",content:"Before a vowel the article becomes l': l'acqua. Caffè carries its stress on the last letter, which is why it is written with an accent. Ordering un caffè in Italy gets you an espresso."},{type:"multiple_choice",question:"What does «il pane» mean?",options:["the bread","the water","the milk"],correct:0,explanation:"«il pane» means “the bread”."},{type:"multiple_choice",question:"What does «il formaggio» mean?",options:["the apple","the cheese","the coffee"],correct:1,explanation:"«il formaggio» means “the cheese”."},{type:"multiple_choice",question:"What does «il tè» mean?",options:["the bread","the water","the tea"],correct:2,explanation:"«il tè» means “the tea”."},{type:"translate",question:"Write in Italian: “the bread”",correct:"il pane",explanation:"“the bread” is «il pane»."},{type:"translate",question:"Write in Italian: “the milk”",correct:"il latte",explanation:"“the milk” is «il latte»."}]},{id:"italian-a1-have",title:"I have",icon:"📚",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"I have",content:"To have: io ho, tu hai, lui ha, noi abbiamo. The h is silent and only there to tell ho apart from o. As in French, age and hunger use to have: ho fame, I am hungry."},{type:"multiple_choice",question:"What does «io ho» mean?",options:["I have","you have","he has"],correct:0,explanation:"«io ho» means “I have”."},{type:"multiple_choice",question:"What does «un libro» mean?",options:["a house","a book","a cat"],correct:1,explanation:"«un libro» means “a book”."},{type:"multiple_choice",question:"What does «un cane» mean?",options:["I have","you have","a dog"],correct:2,explanation:"«un cane» means “a dog”."},{type:"translate",question:"Write in Italian: “I have”",correct:"io ho",explanation:"“I have” is «io ho»."},{type:"translate",question:"Write in Italian: “a cat”",correct:"un gatto",explanation:"“a cat” is «un gatto»."}]}]},{id:"italian-a1-3",title:"Getting around",tier:"A1",unlocked:!0,lessons:[{id:"italian-a1-questions",title:"Questions and directions",icon:"❓",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Questions and directions",content:"Dove, quando, come, perché. Perché means both why and because -- the question and its answer start with the same word. Dov'è is dove è run together: dov'è la stazione?"},{type:"multiple_choice",question:"What does «dove» mean?",options:["where","when","how"],correct:0,explanation:"«dove» means “where”."},{type:"multiple_choice",question:"What does «quanto» mean?",options:["who","how much","to the left"],correct:1,explanation:"«quanto» means “how much”."},{type:"multiple_choice",question:"What does «a destra» mean?",options:["where","when","to the right"],correct:2,explanation:"«a destra» means “to the right”."},{type:"translate",question:"Write in Italian: “where”",correct:"dove",explanation:"“where” is «dove»."},{type:"translate",question:"Write in Italian: “to the right”",correct:"a destra",explanation:"“to the right” is «a destra»."}]},{id:"italian-a1-days",title:"Days and time",icon:"📅",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Days and time",content:"Weekdays from lunedì to venerdì carry the stress on the final i, hence the accent. They are not capitalised. Il lunedì means every Monday; lunedì alone means this Monday."},{type:"multiple_choice",question:"What does «lunedì» mean?",options:["Monday","Tuesday","Wednesday"],correct:0,explanation:"«lunedì» means “Monday”."},{type:"multiple_choice",question:"What does «sabato» mean?",options:["Sunday","Saturday","today"],correct:1,explanation:"«sabato» means “Saturday”."},{type:"multiple_choice",question:"What does «ieri» mean?",options:["Monday","Tuesday","yesterday"],correct:2,explanation:"«ieri» means “yesterday”."},{type:"translate",question:"Write in Italian: “tomorrow”",correct:"domani",explanation:"“tomorrow” is «domani»."},{type:"translate",question:"Write in Italian: “Monday”",correct:"lunedì",explanation:"“Monday” is «lunedì»."}]}]}]},portuguese:{title:"Portuguese Passage",color:"#ef4444",sections:[{id:"portuguese-a1-1",title:"First words",tier:"A1",unlocked:!0,lessons:[{id:"portuguese-a1-greetings",title:"Greetings",icon:"👋",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Greetings",content:"Bom dia until lunch, boa tarde until dark, boa noite after. Thank you agrees with the speaker, not the listener: a man says obrigado, a woman says obrigada. The forms here are European Portuguese; Brazil shares almost all of them."},{type:"multiple_choice",question:"What does «olá» mean?",options:["hello","thank you (said by a man)","good morning"],correct:0,explanation:"«olá» means “hello”."},{type:"multiple_choice",question:"What does «boa noite» mean?",options:["please","good evening / good night","yes"],correct:1,explanation:"«boa noite» means “good evening / good night”."},{type:"multiple_choice",question:"What does «não» mean?",options:["hello","thank you (said by a man)","no"],correct:2,explanation:"«não» means “no”."},{type:"translate",question:"Write in Portuguese: “hello”",correct:"olá",explanation:"“hello” is «olá»."},{type:"translate",question:"Write in Portuguese: “goodbye”",correct:"adeus",explanation:"“goodbye” is «adeus»."}]},{id:"portuguese-a1-introductions",title:"Who I am",icon:"🧑",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Who I am",content:"To be for who you are: eu sou, tu és, ele é, ela é, nós somos. Portuguese has a second to be, estar, for passing states -- sou alto, I am tall, but estou cansado, I am tired. Tu is used in Portugal; Brazil mostly says você é."},{type:"multiple_choice",question:"What does «eu sou» mean?",options:["I am","you are","he is"],correct:0,explanation:"«eu sou» means “I am”."},{type:"multiple_choice",question:"What does «ela é» mean?",options:["we are","she is","my name is"],correct:1,explanation:"«ela é» means “she is”."},{type:"multiple_choice",question:"What does «prazer» mean?",options:["I am","you are","nice to meet you"],correct:2,explanation:"«prazer» means “nice to meet you”."},{type:"translate",question:"Write in Portuguese: “I am”",correct:"eu sou",explanation:"“I am” is «eu sou»."},{type:"translate",question:"Write in Portuguese: “we are”",correct:"nós somos",explanation:"“we are” is «nós somos»."}]},{id:"portuguese-a1-numbers",title:"Numbers 1-10",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers 1-10",content:"Um, dois, três. One and two agree with the noun: um livro but uma casa, dois gatos but duas casas. The tilde marks a nasal vowel, as in não."},{type:"multiple_choice",question:"What does «um» mean?",options:["one","two","three"],correct:0,explanation:"«um» means “one”."},{type:"multiple_choice",question:"What does «seis» mean?",options:["seven","six","eight"],correct:1,explanation:"«seis» means “six”."},{type:"multiple_choice",question:"What does «dez» mean?",options:["one","two","ten"],correct:2,explanation:"«dez» means “ten”."},{type:"translate",question:"Write in Portuguese: “two”",correct:"dois",explanation:"“two” is «dois»."},{type:"translate",question:"Write in Portuguese: “five”",correct:"cinco",explanation:"“five” is «cinco»."}]}]},{id:"portuguese-a1-2",title:"People and things",tier:"A1",unlocked:!0,lessons:[{id:"portuguese-a1-family",title:"Family",icon:"👪",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Family",content:"The words for the are o and a: o pai, a mãe. Os pais means the parents -- the masculine plural covers a mixed pair, so it is the plural of father that stands for both."},{type:"multiple_choice",question:"What does «a mãe» mean?",options:["the mother","the father","the brother"],correct:0,explanation:"«a mãe» means “the mother”."},{type:"multiple_choice",question:"What does «a irmã» mean?",options:["the son","the sister","the daughter"],correct:1,explanation:"«a irmã» means “the sister”."},{type:"multiple_choice",question:"What does «os pais» mean?",options:["the mother","the father","the parents"],correct:2,explanation:"«os pais» means “the parents”."},{type:"translate",question:"Write in Portuguese: “the father”",correct:"o pai",explanation:"“the father” is «o pai»."},{type:"translate",question:"Write in Portuguese: “the brother”",correct:"o irmão",explanation:"“the brother” is «o irmão»."}]},{id:"portuguese-a1-food",title:"Food and drink",icon:"🍞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Food and drink",content:"Água is feminine: a água. Pão ends in a nasal sound, close to pown said through the nose. In a café, um café is an espresso, as in Italy."},{type:"multiple_choice",question:"What does «o pão» mean?",options:["the bread","the water","the milk"],correct:0,explanation:"«o pão» means “the bread”."},{type:"multiple_choice",question:"What does «o queijo» mean?",options:["the apple","the cheese","the coffee"],correct:1,explanation:"«o queijo» means “the cheese”."},{type:"multiple_choice",question:"What does «o chá» mean?",options:["the bread","the water","the tea"],correct:2,explanation:"«o chá» means “the tea”."},{type:"translate",question:"Write in Portuguese: “the milk”",correct:"o leite",explanation:"“the milk” is «o leite»."},{type:"translate",question:"Write in Portuguese: “the cheese”",correct:"o queijo",explanation:"“the cheese” is «o queijo»."}]},{id:"portuguese-a1-have",title:"I have",icon:"📚",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"I have",content:"To have: eu tenho, tu tens, ele tem, nós temos. Age uses to have, as in the other Romance languages: tenho vinte anos. Cão is the word in Portugal; Brazil says cachorro."},{type:"multiple_choice",question:"What does «eu tenho» mean?",options:["I have","you have","he has"],correct:0,explanation:"«eu tenho» means “I have”."},{type:"multiple_choice",question:"What does «um livro» mean?",options:["a house","a book","a cat"],correct:1,explanation:"«um livro» means “a book”."},{type:"multiple_choice",question:"What does «um cão» mean?",options:["I have","you have","a dog"],correct:2,explanation:"«um cão» means “a dog”."},{type:"translate",question:"Write in Portuguese: “I have”",correct:"eu tenho",explanation:"“I have” is «eu tenho»."},{type:"translate",question:"Write in Portuguese: “a cat”",correct:"um gato",explanation:"“a cat” is «um gato»."}]}]},{id:"portuguese-a1-3",title:"Getting around",tier:"A1",unlocked:!0,lessons:[{id:"portuguese-a1-questions",title:"Questions and directions",icon:"❓",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Questions and directions",content:"Onde, quando, como, quanto, quem. The word order of a question is the same as a statement; the rising voice does the work. À esquerda and à direita carry a grave accent because a plus a has merged into one."},{type:"multiple_choice",question:"What does «onde» mean?",options:["where","when","how"],correct:0,explanation:"«onde» means “where”."},{type:"multiple_choice",question:"What does «quanto» mean?",options:["who","how much","to the left"],correct:1,explanation:"«quanto» means “how much”."},{type:"multiple_choice",question:"What does «à direita» mean?",options:["where","when","to the right"],correct:2,explanation:"«à direita» means “to the right”."},{type:"translate",question:"Write in Portuguese: “where”",correct:"onde",explanation:"“where” is «onde»."},{type:"translate",question:"Write in Portuguese: “to the right”",correct:"à direita",explanation:"“to the right” is «à direita»."}]},{id:"portuguese-a1-days",title:"Days and time",icon:"📅",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Days and time",content:"Weekdays are numbered, not named after planets: segunda-feira is second day, because Sunday counts as the first. In speech the -feira is often dropped: até segunda, see you Monday."},{type:"multiple_choice",question:"What does «segunda-feira» mean?",options:["Monday","Tuesday","Wednesday"],correct:0,explanation:"«segunda-feira» means “Monday”."},{type:"multiple_choice",question:"What does «sábado» mean?",options:["Sunday","Saturday","today"],correct:1,explanation:"«sábado» means “Saturday”."},{type:"multiple_choice",question:"What does «ontem» mean?",options:["Monday","Tuesday","yesterday"],correct:2,explanation:"«ontem» means “yesterday”."},{type:"translate",question:"Write in Portuguese: “tomorrow”",correct:"amanhã",explanation:"“tomorrow” is «amanhã»."},{type:"translate",question:"Write in Portuguese: “Sunday”",correct:"domingo",explanation:"“Sunday” is «domingo»."}]}]}]},"math-counting":{title:"Counting",color:"#f43f5e",sections:[{id:"mc-sec",title:"Counting to a hundred",unlocked:!0,lessons:[{id:"mc-l1",title:"Counting to 20",icon:"1",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers in order",content:"Numbers have a fixed order: 1, 2, 3, and so on. Counting up means moving forward in that order; counting down means moving back. Example: after 14 comes 15, and before 15 comes 14."},{type:"multiple_choice",question:"What comes after 14?",options:["13","15","16"],correct:1,explanation:"14 + 1 = 15."},{type:"multiple_choice",question:"What comes before 10?",options:["8","9","11"],correct:1,explanation:"9 + 1 = 10, so 9 comes right before 10."},{type:"translate",question:"Write the number that comes after 19.",correct:"20",explanation:"19 + 1 = 20."},{type:"multiple_choice",question:"Count backwards: 17, 16, 15, __?",options:["14","13","16"],correct:0,explanation:"Each step goes down by one: 15 - 1 = 14."},{type:"translate",question:"How many tens make 20?",correct:"2",explanation:"20 is 2 groups of ten."},{type:"multiple_choice",question:"Which number is missing? 5, 6, __, 8",options:["7","9","4"],correct:0,explanation:"The numbers go up by one each time, so 6 is followed by 7."}]},{id:"mc-l2",title:"Comparing numbers",icon:"<",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Bigger, smaller, or the same",content:"Two numbers can be compared: one can be bigger (>), smaller (<), or they can be equal (=). Example: 9 is bigger than 7, so we write 9 > 7."},{type:"multiple_choice",question:"Which sign goes between 8 and 5? 8 __ 5",options:["<",">","="],correct:1,explanation:"8 is bigger than 5, so the sign is >."},{type:"multiple_choice",question:"Which is bigger, 42 or 24?",options:["42","24","they are equal"],correct:0,explanation:"42 has more tens (4) than 24 (2 tens), so 42 is bigger."},{type:"multiple_choice",question:"13 __ 13",options:["<",">","="],correct:2,explanation:"The same number is neither bigger nor smaller than itself."},{type:"translate",question:"Write the bigger number: 56 or 65",correct:"65",explanation:"65 has 6 tens, 56 has 5 tens, so 65 is bigger."},{type:"multiple_choice",question:"Order from smallest: 30, 3, 13",options:["3, 13, 30","30, 13, 3","13, 3, 30"],correct:0,explanation:"3 is smallest, then 13, then 30."},{type:"multiple_choice",question:"Which is smaller, 19 or 91?",options:["19","91","equal"],correct:0,explanation:"19 has 1 ten, 91 has 9 tens, so 19 is smaller."}]},{id:"mc-l3",title:"Adding within 20",icon:"+",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Putting numbers together",content:"Adding means putting two amounts together to make one total. Example: 6 + 7 = 13, because starting at 6 and counting on 7 more lands on 13."},{type:"translate",question:"6 + 7 = ?",correct:"13",explanation:"6 + 7 = 13."},{type:"multiple_choice",question:"8 + 5 = ?",options:["12","13","14"],correct:1,explanation:"8 + 5 = 13."},{type:"translate",question:"9 + 9 = ?",correct:"18",explanation:"9 + 9 = 18."},{type:"multiple_choice",question:"There are 7 red apples and 6 green apples. How many apples in total?",options:["13","12","14"],correct:0,explanation:"7 + 6 = 13."},{type:"translate",question:"10 + 8 = ?",correct:"18",explanation:"10 + 8 = 18."},{type:"multiple_choice",question:"4 + 4 + 4 = ?",options:["8","12","16"],correct:1,explanation:"4 + 4 = 8, 8 + 4 = 12."}]},{id:"mc-l4",title:"Taking away within 20",icon:"-",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Taking some away",content:"Subtracting means taking an amount away from a total. Example: 15 - 6 = 9, because 6 taken away from 15 leaves 9."},{type:"translate",question:"15 - 6 = ?",correct:"9",explanation:"15 - 6 = 9."},{type:"multiple_choice",question:"18 - 9 = ?",options:["8","9","10"],correct:1,explanation:"18 - 9 = 9."},{type:"translate",question:"20 - 12 = ?",correct:"8",explanation:"20 - 12 = 8."},{type:"multiple_choice",question:"There were 16 birds; 7 flew away. How many are left?",options:["9","8","10"],correct:0,explanation:"16 - 7 = 9."},{type:"translate",question:"14 - 7 = ?",correct:"7",explanation:"14 - 7 = 7."},{type:"multiple_choice",question:"17 - 8 = ?",options:["9","8","10"],correct:0,explanation:"17 - 8 = 9."}]},{id:"mc-l5",title:"Tens and ones",icon:"10",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Every number is made of tens and ones",content:"A two-digit number is made of tens and ones. Example: 43 is 4 tens and 3 ones, because 4 tens is 40, plus 3 ones is 43."},{type:"multiple_choice",question:"How many tens in 67?",options:["6","7","67"],correct:0,explanation:"67 = 6 tens and 7 ones."},{type:"multiple_choice",question:"How many ones in 67?",options:["6","7","0"],correct:1,explanation:"67 = 6 tens and 7 ones."},{type:"translate",question:"4 tens and 5 ones make what number?",correct:"45",explanation:"4 tens is 40, plus 5 ones is 45."},{type:"multiple_choice",question:"Which number has 8 tens and 2 ones?",options:["28","82","80"],correct:1,explanation:"8 tens is 80, plus 2 ones is 82."},{type:"translate",question:"How many tens in 90?",correct:"9",explanation:"90 = 9 tens and 0 ones."},{type:"multiple_choice",question:"3 tens and 0 ones is",options:["3","30","300"],correct:1,explanation:"3 tens is 30."}]},{id:"mc-l6",title:"Adding within 100",icon:"+",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Adding two-digit numbers",content:"To add two two-digit numbers, add the ones, then the tens. Example: 34 + 25 -- ones: 4 + 5 = 9, tens: 30 + 20 = 50, total: 59."},{type:"translate",question:"34 + 25 = ?",correct:"59",explanation:"34 + 25 = 59."},{type:"multiple_choice",question:"42 + 31 = ?",options:["73","72","74"],correct:0,explanation:"42 + 31 = 73."},{type:"translate",question:"18 + 26 = ?",correct:"44",explanation:"18 + 26 = 44."},{type:"multiple_choice",question:"A shop sold 27 apples in the morning and 35 in the afternoon. How many in total?",options:["62","61","63"],correct:0,explanation:"27 + 35 = 62."},{type:"translate",question:"48 + 19 = ?",correct:"67",explanation:"48 + 19 = 67."},{type:"multiple_choice",question:"56 + 27 = ?",options:["83","82","84"],correct:0,explanation:"56 + 27 = 83."}]},{id:"mc-l7",title:"Taking away within 100",icon:"-",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Subtracting two-digit numbers",content:"To subtract two-digit numbers, sometimes a ten must be borrowed. Example: 52 - 27 -- 2 ones cannot take away 7, so borrow a ten: 12 - 7 = 5, and 4 tens - 2 tens = 2 tens, giving 25."},{type:"translate",question:"52 - 27 = ?",correct:"25",explanation:"52 - 27 = 25."},{type:"multiple_choice",question:"80 - 34 = ?",options:["46","44","56"],correct:0,explanation:"80 - 34 = 46."},{type:"translate",question:"63 - 19 = ?",correct:"44",explanation:"63 - 19 = 44."},{type:"multiple_choice",question:"There were 90 sweets; 58 were eaten. How many are left?",options:["32","42","22"],correct:0,explanation:"90 - 58 = 32."},{type:"translate",question:"100 - 45 = ?",correct:"55",explanation:"100 - 45 = 55."},{type:"multiple_choice",question:"71 - 38 = ?",options:["33","23","43"],correct:0,explanation:"71 - 38 = 33."}]},{id:"mc-l8",title:"Word problems within a hundred",icon:"?",xp:30,unlocked:!0,type:"lesson",work:"control",exercises:[{type:"lecture",question:"Reading before calculating",content:"A word problem gives numbers inside a story. First decide whether things are joined (add) or removed (subtract), then do the sum. Example: 23 stickers, 15 more bought -- joined, so add: 23 + 15 = 38."},{type:"multiple_choice",question:"Maria has 23 stickers. She buys 15 more. How many now?",options:["38","37","39"],correct:0,explanation:"23 + 15 = 38."},{type:"translate",question:"A box has 40 pencils. 16 are given away. How many are left?",correct:"24",explanation:"40 - 16 = 24."},{type:"multiple_choice",question:"There are 12 boys and 17 girls in a class. How many pupils?",options:["29","28","30"],correct:0,explanation:"12 + 17 = 29."},{type:"translate",question:"A farmer had 65 hens. He sold 28. How many are left?",correct:"37",explanation:"65 - 28 = 37."},{type:"multiple_choice",question:"Tom read 14 pages on Monday and 19 on Tuesday. How many pages in total?",options:["33","32","34"],correct:0,explanation:"14 + 19 = 33."},{type:"translate",question:"There were 50 cars in the car park. 23 left. How many remain?",correct:"27",explanation:"50 - 23 = 27."}]}]}]},"math-operations":{title:"Four operations",color:"#fb923c",sections:[{id:"mo-sec",title:"Multiply, divide, and solve",unlocked:!0,lessons:[{id:"mo-l1",title:"Multiplication as repeated addition",icon:"x",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Adding the same number many times",content:"Multiplication is repeated addition of the same number. Example: 4 x 3 means 4 added 3 times: 4 + 4 + 4 = 12."},{type:"translate",question:"4 x 3 = ?",correct:"12",explanation:"4 + 4 + 4 = 12."},{type:"multiple_choice",question:"5 x 2 = ?",options:["7","10","12"],correct:1,explanation:"5 + 5 = 10."},{type:"translate",question:"6 x 6 = ?",correct:"36",explanation:"6 x 6 = 36."},{type:"multiple_choice",question:"7 x 3 = ?",options:["21","20","24"],correct:0,explanation:"7 + 7 + 7 = 21."},{type:"translate",question:"8 x 4 = ?",correct:"32",explanation:"8 x 4 = 32."},{type:"multiple_choice",question:"There are 5 bags with 6 apples each. How many apples in total?",options:["30","25","35"],correct:0,explanation:"5 x 6 = 30."}]},{id:"mo-l2",title:"Multiplication tables",icon:"x",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Knowing the facts by heart",content:"Knowing multiplication facts up to 10 x 10 saves working them out every time. Example: 7 x 8 = 56 -- once known, it is instant."},{type:"translate",question:"7 x 8 = ?",correct:"56",explanation:"7 x 8 = 56."},{type:"multiple_choice",question:"9 x 6 = ?",options:["54","56","52"],correct:0,explanation:"9 x 6 = 54."},{type:"translate",question:"12 x 5 = ?",correct:"60",explanation:"12 x 5 = 60."},{type:"multiple_choice",question:"6 x 9 = ?",options:["54","48","56"],correct:0,explanation:"6 x 9 = 54, the same as 9 x 6."},{type:"translate",question:"7 x 7 = ?",correct:"49",explanation:"7 x 7 = 49."},{type:"multiple_choice",question:"8 x 8 = ?",options:["64","72","56"],correct:0,explanation:"8 x 8 = 64."}]},{id:"mo-l3",title:"Division as sharing",icon:"/",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Splitting into equal groups",content:"Division splits a total into equal groups. It is the inverse of multiplication: 12 / 3 = 4 because 4 x 3 = 12."},{type:"translate",question:"12 / 3 = ?",correct:"4",explanation:"12 / 3 = 4, since 4 x 3 = 12."},{type:"multiple_choice",question:"20 / 4 = ?",options:["5","4","6"],correct:0,explanation:"20 / 4 = 5, since 5 x 4 = 20."},{type:"translate",question:"45 / 9 = ?",correct:"5",explanation:"45 / 9 = 5, since 5 x 9 = 45."},{type:"multiple_choice",question:"24 sweets shared equally among 6 children. How many each?",options:["4","3","5"],correct:0,explanation:"24 / 6 = 4."},{type:"translate",question:"36 / 6 = ?",correct:"6",explanation:"36 / 6 = 6."},{type:"multiple_choice",question:"Which is the inverse fact of 7 x 8 = 56?",options:["56 / 8 = 6","56 / 8 = 7","8 / 7 = 56"],correct:1,explanation:"56 / 8 = 7, undoing the multiplication."}]},{id:"mo-l4",title:"Division with remainder",icon:"/",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"When it does not divide evenly",content:"Not every division comes out even. What is left over is the remainder. Example: 17 / 5 -- 5 x 3 = 15, and 17 - 15 = 2 left over, so 17 / 5 is 3 remainder 2."},{type:"multiple_choice",question:"17 / 5 = ? remainder ?",options:["3 remainder 2","3 remainder 1","4 remainder 0"],correct:0,explanation:"5 x 3 = 15, and 17 - 15 = 2."},{type:"translate",question:"How many times does 4 fit into 22, ignoring what is left over?",correct:"5",explanation:"4 x 5 = 20, which fits into 22 with 2 left over."},{type:"multiple_choice",question:"23 / 6 = ? remainder ?",options:["3 remainder 5","4 remainder 1","3 remainder 4"],correct:0,explanation:"6 x 3 = 18, and 23 - 18 = 5."},{type:"translate",question:"25 sweets shared among 4 children equally, how many are left over?",correct:"1",explanation:"4 x 6 = 24, and 25 - 24 = 1."},{type:"multiple_choice",question:"31 / 7 = ? remainder ?",options:["4 remainder 3","4 remainder 2","5 remainder 0"],correct:0,explanation:"7 x 4 = 28, and 31 - 28 = 3."},{type:"translate",question:"How many full weeks are in 17 days?",correct:"2",explanation:"7 x 2 = 14 fits into 17, with 3 days left over."}]},{id:"mo-l5",title:"Order of operations",icon:"()",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"What runs first",content:"Multiplication and division are done before addition and subtraction, unless brackets say otherwise. Example: 2 + 3 x 4 -- the multiplication runs first: 3 x 4 = 12, then 2 + 12 = 14."},{type:"translate",question:"2 + 3 x 4 = ?",correct:"14",explanation:"3 x 4 = 12 first, then 2 + 12 = 14."},{type:"multiple_choice",question:"10 - 2 x 3 = ?",options:["4","24","8"],correct:0,explanation:"2 x 3 = 6 first, then 10 - 6 = 4."},{type:"translate",question:"20 / 4 + 3 = ?",correct:"8",explanation:"20 / 4 = 5 first, then 5 + 3 = 8."},{type:"multiple_choice",question:"(2 + 3) x 4 = ?",options:["20","14","9"],correct:0,explanation:"Brackets run first: 2 + 3 = 5, then 5 x 4 = 20."},{type:"translate",question:"6 x 2 - 5 = ?",correct:"7",explanation:"6 x 2 = 12 first, then 12 - 5 = 7."},{type:"multiple_choice",question:"15 - 6 / 2 = ?",options:["12","4.5","6"],correct:0,explanation:"6 / 2 = 3 first, then 15 - 3 = 12."}]},{id:"mo-l6",title:"Multi-step word problems",icon:"?",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Breaking a problem into steps",content:"A harder word problem needs more than one step. Work out what the first step gives you, then use that result for the next step. Example: 5 rows of 9 chairs, 7 broken -- first 5 x 9 = 45, then 45 - 7 = 38."},{type:"multiple_choice",question:"A box holds 6 eggs. How many eggs in 8 boxes?",options:["48","42","54"],correct:0,explanation:"6 x 8 = 48."},{type:"translate",question:"There are 5 rows of chairs with 9 chairs in each row. 7 chairs are broken. How many working chairs?",correct:"38",explanation:"5 x 9 = 45, then 45 - 7 = 38."},{type:"multiple_choice",question:"A baker makes 60 buns and puts them equally into 5 boxes. How many buns per box?",options:["12","10","15"],correct:0,explanation:"60 / 5 = 12."},{type:"translate",question:"3 packs of pencils with 8 pencils each are shared equally between 4 children. How many pencils per child?",correct:"6",explanation:"3 x 8 = 24, then 24 / 4 = 6."},{type:"multiple_choice",question:"A class of 24 pupils is split into teams of 4. How many teams?",options:["6","5","8"],correct:0,explanation:"24 / 4 = 6."},{type:"translate",question:"A farmer has 7 baskets with 9 eggs each. He sells 40 eggs. How many eggs are left?",correct:"23",explanation:"7 x 9 = 63, then 63 - 40 = 23."}]},{id:"mo-l7",title:"Multiplying two-digit numbers",icon:"x",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Multiplying by a one-digit number",content:"A two-digit number can be split into tens and ones, each multiplied separately, then added. Example: 23 x 4 -- 20 x 4 = 80, and 3 x 4 = 12, so 80 + 12 = 92."},{type:"translate",question:"23 x 4 = ?",correct:"92",explanation:"20 x 4 = 80, 3 x 4 = 12, 80 + 12 = 92."},{type:"multiple_choice",question:"16 x 5 = ?",options:["80","75","85"],correct:0,explanation:"10 x 5 = 50, 6 x 5 = 30, 50 + 30 = 80."},{type:"translate",question:"32 x 3 = ?",correct:"96",explanation:"30 x 3 = 90, 2 x 3 = 6, 90 + 6 = 96."},{type:"multiple_choice",question:"14 x 6 = ?",options:["84","74","94"],correct:0,explanation:"10 x 6 = 60, 4 x 6 = 24, 60 + 24 = 84."},{type:"translate",question:"25 x 4 = ?",correct:"100",explanation:"20 x 4 = 80, 5 x 4 = 20, 80 + 20 = 100."},{type:"multiple_choice",question:"18 x 5 = ?",options:["90","85","95"],correct:0,explanation:"10 x 5 = 50, 8 x 5 = 40, 50 + 40 = 90."}]},{id:"mo-l8",title:"Dividing larger numbers",icon:"/",xp:35,unlocked:!0,type:"lesson",work:"control",exercises:[{type:"lecture",question:"Dividing a bigger number",content:"A larger division can be checked by asking what times the divisor gives the total. Example: 96 / 4 -- 4 x 24 = 96, so 96 / 4 = 24."},{type:"translate",question:"96 / 4 = ?",correct:"24",explanation:"4 x 24 = 96."},{type:"multiple_choice",question:"84 / 6 = ?",options:["14","12","16"],correct:0,explanation:"6 x 14 = 84."},{type:"translate",question:"72 / 8 = ?",correct:"9",explanation:"8 x 9 = 72."},{type:"multiple_choice",question:"108 / 9 = ?",options:["12","11","13"],correct:0,explanation:"9 x 12 = 108."},{type:"translate",question:"144 / 12 = ?",correct:"12",explanation:"12 x 12 = 144."},{type:"multiple_choice",question:"63 / 7 = ?",options:["9","8","10"],correct:0,explanation:"7 x 9 = 63."}]}]}]},"math-fractions":{title:"Fractions and parts",color:"#8b5cf6",sections:[{id:"mf-sec",title:"Fractions, per cent, and ratio",unlocked:!0,lessons:[{id:"mf-l1",title:"What a fraction is",icon:"1/2",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Parts of a whole",content:"A fraction shows equal parts of a whole. In 3/4, the bottom number (denominator) says how many equal parts the whole is cut into, and the top number (numerator) says how many of them are taken."},{type:"multiple_choice",question:"A pizza is cut into 8 equal slices; you eat 3. What fraction did you eat?",options:["3/8","8/3","3/5"],correct:0,explanation:"3 slices out of 8 equal slices is 3/8."},{type:"multiple_choice",question:"Which fraction is shaded if 2 out of 5 equal parts are coloured?",options:["2/5","5/2","2/3"],correct:0,explanation:"2 parts out of 5 is 2/5."},{type:"translate",question:"Write as a fraction: 1 part out of 4",correct:"1/4",explanation:"1 out of 4 equal parts is 1/4."},{type:"multiple_choice",question:"In the fraction 5/9, what is the denominator?",options:["5","9","4"],correct:1,explanation:"The denominator is the bottom number: 9."},{type:"translate",question:"In the fraction 3/7, what is the numerator?",correct:"3",explanation:"The numerator is the top number: 3."},{type:"multiple_choice",question:"Which fraction is bigger than a whole (improper)?",options:["3/4","4/3","2/5"],correct:1,explanation:"4/3 has more parts (4) than make a whole (3), so it is bigger than 1."}]},{id:"mf-l2",title:"Equivalent fractions",icon:"=",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The same amount, different parts",content:"Multiplying (or dividing) both the numerator and the denominator by the same number gives an equivalent fraction, worth the same amount. Example: 1/2 = 2/4, because both parts were multiplied by 2."},{type:"multiple_choice",question:"Which fraction equals 1/2?",options:["2/4","2/5","3/5"],correct:0,explanation:"1/2 = 2/4, since both parts are multiplied by 2."},{type:"translate",question:"3/4 = ? / 8 (find the missing numerator)",correct:"6",explanation:"4 x 2 = 8, so the numerator is also x2: 3 x 2 = 6."},{type:"multiple_choice",question:"Which fraction equals 2/3?",options:["4/6","4/5","3/4"],correct:0,explanation:"2/3 = 4/6, since both parts are multiplied by 2."},{type:"translate",question:"1/5 = 2 / ? (find the missing denominator)",correct:"10",explanation:"1 x 2 = 2, so the denominator is also x2: 5 x 2 = 10."},{type:"multiple_choice",question:"Simplify 4/8 to lowest terms",options:["1/2","2/4","1/4"],correct:0,explanation:"4/8 divided by 4 on both parts is 1/2."},{type:"translate",question:"Simplify 6/9 to lowest terms",correct:"2/3",explanation:"6/9 divided by 3 on both parts is 2/3."}]},{id:"mf-l3",title:"Comparing fractions",icon:"<",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Which fraction is bigger",content:"With the same denominator, the bigger numerator wins. With different denominators, convert to a common one first, or think in terms of size: 3/4 is more than half, 1/3 is less than half."},{type:"multiple_choice",question:"Which is bigger, 3/8 or 5/8?",options:["3/8","5/8","equal"],correct:1,explanation:"Same denominator, so compare numerators: 5 > 3."},{type:"multiple_choice",question:"Which is bigger, 1/2 or 1/3?",options:["1/2","1/3","equal"],correct:0,explanation:"Cutting into fewer parts (2) makes each part bigger than cutting into more parts (3)."},{type:"multiple_choice",question:"Which is bigger, 2/3 or 3/4?",options:["2/3","3/4","equal"],correct:1,explanation:"2/3 is about 0.67 and 3/4 is 0.75, so 3/4 is bigger."},{type:"multiple_choice",question:"Which is smaller, 5/6 or 7/12?",options:["5/6","7/12","equal"],correct:1,explanation:"5/6 is about 0.83 and 7/12 is about 0.58, so 7/12 is smaller."},{type:"multiple_choice",question:"Order from smallest: 1/4, 1/2, 1/8",options:["1/8, 1/4, 1/2","1/2, 1/4, 1/8","1/4, 1/8, 1/2"],correct:0,explanation:"More parts means smaller pieces: 1/8 is smallest, 1/2 is largest."},{type:"multiple_choice",question:"Which is bigger, 3/5 or 2/5?",options:["3/5","2/5","equal"],correct:0,explanation:"Same denominator, so compare numerators: 3 > 2."}]},{id:"mf-l4",title:"Adding and subtracting fractions",icon:"+",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Same denominator, combine the tops",content:"When two fractions share the same denominator, add or subtract the numerators and keep the denominator. Example: 1/5 + 2/5 = 3/5."},{type:"translate",question:"1/5 + 2/5 = ?",correct:"3/5",explanation:"1 + 2 = 3, denominator stays 5."},{type:"multiple_choice",question:"3/7 + 2/7 = ?",options:["5/7","5/14","1/7"],correct:0,explanation:"3 + 2 = 5, denominator stays 7."},{type:"translate",question:"5/8 - 2/8 = ?",correct:"3/8",explanation:"5 - 2 = 3, denominator stays 8."},{type:"multiple_choice",question:"7/9 - 4/9 = ?",options:["3/9","4/9","1/9"],correct:0,explanation:"7 - 4 = 3, denominator stays 9."},{type:"translate",question:"2/6 + 3/6 = ?",correct:"5/6",explanation:"2 + 3 = 5, denominator stays 6."},{type:"multiple_choice",question:"1/4 + 1/4 = ?",options:["2/4","1/8","3/4"],correct:0,explanation:"1 + 1 = 2, denominator stays 4."}]},{id:"mf-l5",title:"Fractions, decimals and per cent",icon:"%",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Three ways to write the same amount",content:"A fraction, a decimal and a per cent can name the same amount. 1/2 = 0.5 = 50%. To get a percent from a fraction, divide the top by the bottom and multiply by 100."},{type:"multiple_choice",question:"1/4 as a decimal is",options:["0.25","0.4","0.14"],correct:0,explanation:"1 divided by 4 is 0.25."},{type:"multiple_choice",question:"1/2 as a per cent is",options:["50%","25%","12%"],correct:0,explanation:"1/2 = 0.5, and 0.5 x 100 = 50%."},{type:"translate",question:"3/4 as a per cent (number only, no % sign)",correct:"75",explanation:"3/4 = 0.75, and 0.75 x 100 = 75."},{type:"multiple_choice",question:"0.75 as a fraction is",options:["3/4","7/5","3/5"],correct:0,explanation:"0.75 = 75/100, which simplifies to 3/4."},{type:"translate",question:"1/5 as a decimal",correct:"0.2",explanation:"1 divided by 5 is 0.2."},{type:"multiple_choice",question:"20% as a fraction in lowest terms is",options:["1/5","1/4","2/10"],correct:0,explanation:"20/100 simplifies to 1/5."}]},{id:"mf-l6",title:"Per cent of a number",icon:"%",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Taking a percentage of an amount",content:"To find a per cent of a number, turn the per cent into a fraction (or decimal) and multiply. Example: 10% of 50 -- 10% is 10/100, so 10/100 x 50 = 5."},{type:"translate",question:"10% of 50 = ?",correct:"5",explanation:"10% of 50 = 5."},{type:"multiple_choice",question:"25% of 80 = ?",options:["20","25","16"],correct:0,explanation:"25% is a quarter: 80 / 4 = 20."},{type:"translate",question:"50% of 46 = ?",correct:"23",explanation:"50% is half: 46 / 2 = 23."},{type:"multiple_choice",question:"A 200 g bag is 20% sugar. How many grams of sugar?",options:["40","20","4"],correct:0,explanation:"20% of 200 = 40."},{type:"translate",question:"10% of 120 = ?",correct:"12",explanation:"10% of 120 = 12."},{type:"multiple_choice",question:"A shirt costs 40 and is reduced by 25%. How much is taken off the price?",options:["10","15","20"],correct:0,explanation:"25% of 40 = 10."}]},{id:"mf-l7",title:"Ratio basics",icon:":",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Comparing two amounts",content:"A ratio compares two amounts. 2:3 means for every 2 of the first there are 3 of the second. A ratio can be simplified the same way a fraction can, by dividing both sides by the same number."},{type:"multiple_choice",question:"A recipe uses flour and sugar in ratio 3:1. If there are 3 cups of flour, how much sugar?",options:["1 cup","3 cups","1/3 cup"],correct:0,explanation:"3:1 with 3 cups of flour means 1 cup of sugar."},{type:"translate",question:"Simplify the ratio 10:5 to lowest terms (write as a:b, e.g. 2:1)",correct:"2:1",explanation:"10:5 divided by 5 on both sides is 2:1."},{type:"multiple_choice",question:"A class has 12 boys and 8 girls. What is the ratio of boys to girls in lowest terms?",options:["3:2","2:3","4:3"],correct:0,explanation:"12:8 divided by 4 on both sides is 3:2."},{type:"translate",question:"Simplify the ratio 15:20 to lowest terms",correct:"3:4",explanation:"15:20 divided by 5 on both sides is 3:4."},{type:"multiple_choice",question:"A ratio of 1:4 means for every 1 part of the first there are how many parts of the second?",options:["4","1","5"],correct:0,explanation:"1:4 means 4 parts of the second for every 1 part of the first."},{type:"translate",question:"Share 30 sweets in the ratio 2:3. How many does the larger share get?",correct:"18",explanation:"2 + 3 = 5 parts, each part is 6, larger share is 3 x 6 = 18."}]},{id:"mf-l8",title:"Mixed word problems",icon:"?",xp:35,unlocked:!0,type:"lesson",work:"control",exercises:[{type:"lecture",question:"Fractions, per cent and ratio together",content:"Real problems mix fractions, per cent and ratio. The same idea underlies all three: a part compared to a whole. Read carefully to see which form the problem is using."},{type:"multiple_choice",question:"A tank is 3/4 full of 40 litres capacity. How many litres are in it?",options:["30","20","35"],correct:0,explanation:"3/4 of 40 = 30."},{type:"translate",question:"A shop had 60 shirts. 30% were sold. How many shirts are left?",correct:"42",explanation:"30% of 60 = 18 sold, 60 - 18 = 42 left."},{type:"multiple_choice",question:"Two bags of marbles are shared in the ratio 3:5. If there are 24 marbles in total, how many in the smaller bag?",options:["9","15","12"],correct:0,explanation:"3 + 5 = 8 parts, each part is 3, smaller bag is 3 x 3 = 9."},{type:"translate",question:"1/3 of a class of 27 pupils walk to school. How many pupils walk?",correct:"9",explanation:"1/3 of 27 = 9."},{type:"multiple_choice",question:"A price of 50 is increased by 10%. What is the new price?",options:["55","51","60"],correct:0,explanation:"10% of 50 = 5, and 50 + 5 = 55."},{type:"translate",question:"3/5 of 40 sweets are red. How many sweets are red?",correct:"24",explanation:"3/5 of 40 = 24."}]}]}]}};e.s(["COURSES",0,o],69251)}]);